setup = setup_aux()
DIM = 128
NLAYERS = 2

class Block(nn.Module):
    def __init__(self):
        super().__init__()
        self.up = nn.Linear(DIM, DIM * 4)
        self.down = nn.Linear(DIM * 4, DIM)
        self.ln = nn.LayerNorm(DIM)
    def forward(self, x):
        out = setup["call"](evolved_fn)
        h = self.ln(x)
        h = setup["apply"](h, out)
        h = self.up(h); h = torch.relu(h); h = self.down(h)
        return x + h

torch.manual_seed(0)
model = nn.Sequential(*[Block() for _ in range(NLAYERS)]).to(device)
opt = torch.optim.SGD(model.parameters(), lr=1e-4)

N_ITERS = int(os.environ.get("N_ITERS", "100"))
# warmup
x = torch.randn(4, DIM).to(device)
for _ in range(3):
    y = model(x)
    loss = y.pow(2).mean()
    loss.backward()
    opt.step(); opt.zero_grad()
    xm.mark_step()

# timed
torch.manual_seed(1)
x = torch.randn(4, DIM).to(device)
t0 = time.perf_counter()
for _ in range(N_ITERS):
    y = model(x)
    loss = y.pow(2).mean()
    loss.backward()
    opt.step(); opt.zero_grad()
    xm.mark_step()
xm.mark_step()
xm.wait_device_ops()
t1 = time.perf_counter()
if rank == 0:
    print(f"RT_TIME_MS_PER_ITER {1000.0 * (t1-t0) / N_ITERS:.4f}", flush=True)
